from pathlib import Path
p=Path(__file__).resolve().parents[1]/'dashboard'/'index.html'
s=p.read_text(encoding='utf-8')
s=s.replace('const [h,o,s,l,f]=await Promise.all(base);s=s||{};', 'let [h,o,s,l,f]=await Promise.all(base);s=s||{};')
css='''body[data-page="visual"]{background:#f2f2f7;color:#1c1c1e}body[data-page="visual"] header{background:#f2f2f7f2;border-bottom-color:#d9d9df}body[data-page="visual"] .brand-sub,body[data-page="visual"] .clock{color:#8e8e93}body[data-page="visual"] .mark{background:#fff;border-color:#d1d1d6;color:#007aff;border-radius:10px}body[data-page="visual"] .brand-title{color:#1c1c1e}body[data-page="visual"] .page-nav{border-bottom:0;gap:7px;padding-top:8px;padding-bottom:8px}body[data-page="visual"] .page-nav button{border:0;border-radius:18px;background:transparent;color:#636366;padding:8px 14px}body[data-page="visual"] .page-nav button.active{background:#fff;color:#007aff;border:0}body[data-page="visual"] .status{background:#fff;border-color:#d1d1d6;color:#3a3a3c;border-radius:18px}body[data-page="visual"] .dot.ok{background:#34c759}body[data-page="visual"] #themeSelect{display:none}body[data-page="visual"] main{max-width:720px;padding:22px 16px 94px}body[data-page="visual"] .hero{margin-bottom:18px}body[data-page="visual"] .hero h1{font-size:36px;letter-spacing:-.04em;color:#1c1c1e}body[data-page="visual"] .hero p{color:#636366;font-size:13px}body[data-page="visual"] .hero-side{color:#8e8e93}body[data-page="visual"] .visual-grid{display:flex;flex-direction:column;gap:12px}body[data-page="visual"] .chart-card,body[data-page="visual"] .card{background:#fff;border:1px solid #e5e5ea;border-radius:20px;padding:18px;box-shadow:0 1px 2px #0000000a}body[data-page="visual"] .chart-head strong,body[data-page="visual"] .card h2{color:#1c1c1e}body[data-page="visual"] .chart-head span,body[data-page="visual"] .refresh-note{color:#8e8e93}body[data-page="visual"] .chart-grid{stroke:#e5e5ea}body[data-page="visual"] .chart-line{stroke:#007aff;stroke-width:3}body[data-page="visual"] .chart-area{fill:#007aff;opacity:.06}body[data-page="visual"] .section-title{color:#1c1c1e;margin:24px 4px 10px}body[data-page="visual"] .section-title:after{background:#d1d1d6}body[data-page="visual"] .tag{color:#8e8e93}body[data-page="visual"] .notice{background:#f2f2f7;border-color:#e5e5ea;color:#636366;border-radius:14px}body[data-page="visual"] .table-wrap{border-color:#e5e5ea;border-radius:14px}body[data-page="visual"] .table th{background:#f2f2f7;color:#8e8e93}body[data-page="visual"] .table td{color:#3a3a3c;border-color:#e5e5ea}body[data-page="visual"] .btn{background:#007aff;color:#fff;border:0;border-radius:18px}body[data-page="visual"] .ios-bottom{display:flex}body[data-page="story"] .page-nav button.active{color:var(--accent)}.ios-bottom{display:none;position:fixed;z-index:9;left:12px;right:12px;bottom:12px;height:64px;align-items:center;justify-content:space-around;background:#fffffff2;border:1px solid #d1d1d6;border-radius:22px;color:#8e8e93;box-shadow:0 5px 18px #00000012}.ios-bottom button{border:0;background:none;color:inherit;font-size:10px;display:flex;flex-direction:column;align-items:center;gap:4px;cursor:pointer}.ios-bottom button.active{color:#007aff}.ios-bottom b{font-size:20px;font-weight:400;line-height:18px}@media(max-width:560px){body[data-page="visual"] .page-nav{display:none}body[data-page="visual"] .hero h1{font-size:32px}}
'''
s=s.replace('</style>',css+'</style>',1)
anchor='</section>\n<section id="page-story"'
insert='''<div class="ios-bottom"><button data-page="overview"><b>⌂</b>Overview</button><button class="active" data-page="visual"><b>◌</b>Visual</button><button data-page="story"><b>☰</b>Story</button></div></section>
<section id="page-story"'''
if 'class="ios-bottom"' not in s:
    s=s.replace(anchor,insert,1)
s=s.replace("document.querySelectorAll('.page-nav button').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));", "document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));")
p.write_text(s,encoding='utf-8')
print('unavailable bug and mobile visual page fixed')
